vector<int> dijkstra(vector<vector<pair<int,int>>>& g, int src){
    int n=g.size(); vector<int> d(n,INT_MAX); d[src]=0;
    priority_queue<pair<int,int>,vector<pair<int,int>>,greater<>> pq; pq.push({0,src});
    while(!pq.empty()){auto[du,u]=pq.top();pq.pop();if(du>d[u])continue;
